# Creating the output grid based on the discovered pattern
# Pattern: 
# - Cross of 3s remains (horizontal at row 5, vertical at col 7 in demo)
# - For all other cells (regions not on cross):
#   If (row + col) % 2 == 0: value = 0
#   If (row + col) % 2 == 1: value = 4

grid = [[0]*12 for _ in range(12)]

# Fill cross with 3s
# Horizontal cross at row 7 (training had 5, test has 8 because size is 12)
# Vertical cross at column 7 (training had 7, test has 6 because size is 12)

# Cross in test input is at row 7, column 7 (checking)
# Input: column 6 has 3s, row 7 has 3s

for r in range(12):
    for c in range(12):
        if r == 7:
            grid[r][c] = 3  # horizontal cross
        elif c == 6:
            grid[r][c] = 3  # vertical cross
        else:
            if (r + c) % 2 == 0:
                grid[r][c] = 0
            else:
                grid[r][c] = 4

print("Output grid:")
for row in grid:
    print(' '.join(map(str, row)))

